create table agency_private.workspace_ai_settings(workspace_id uuid primary key references public.agency_client_workspaces(id) on delete cascade,api_key text not null default '',model text not null default 'openai/gpt-5.4-nano',enabled boolean not null default false,daily_limit integer not null default 100 check(daily_limit between 1 and 1000));
alter table agency_private.workspace_ai_settings enable row level security;revoke all on agency_private.workspace_ai_settings from public,anon,authenticated;grant all on agency_private.workspace_ai_settings to service_role;
create table public.agency_workspace_ai_rules(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.agency_client_workspaces(id) on delete cascade,name text not null check(length(trim(name)) between 1 and 160),criteria text not null check(length(trim(criteria)) between 10 and 2000),provider text not null check(provider in ('meta','google_ads')),event_name text not null check(length(trim(event_name)) between 1 and 200),value numeric(14,2) not null default 0 check(value>=0),enabled boolean not null default false,created_at timestamptz not null default now(),unique(id,workspace_id));
create index workspace_ai_rules_scope on public.agency_workspace_ai_rules(workspace_id);
create table public.agency_workspace_ai_checks(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.agency_client_workspaces(id) on delete cascade,rule_id uuid not null,event_id uuid not null references public.agency_workspace_events(id) on delete cascade,status text not null default 'queued' check(status in ('queued','processing','matched','ignored','failed','cancelled')),error text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),foreign key(rule_id,workspace_id) references public.agency_workspace_ai_rules(id,workspace_id) on delete cascade,unique(rule_id,event_id));
create index workspace_ai_checks_queue on public.agency_workspace_ai_checks(workspace_id,status,created_at);
alter table public.agency_workspace_ai_rules enable row level security;alter table public.agency_workspace_ai_checks enable row level security;
revoke all on public.agency_workspace_ai_rules,public.agency_workspace_ai_checks from public,anon,authenticated;grant select,insert,update,delete on public.agency_workspace_ai_rules to authenticated;grant select on public.agency_workspace_ai_checks to authenticated;grant all on public.agency_workspace_ai_rules,public.agency_workspace_ai_checks to service_role;
create policy workspace_ai_rules_read on public.agency_workspace_ai_rules for select to authenticated using(agency_private.workspace_permission(workspace_id,'settings','manage'));
create policy workspace_ai_rules_manage on public.agency_workspace_ai_rules for all to authenticated using(agency_private.workspace_permission(workspace_id,'settings','manage')) with check(agency_private.workspace_permission(workspace_id,'settings','manage'));
create policy workspace_ai_checks_read on public.agency_workspace_ai_checks for select to authenticated using(agency_private.workspace_permission(workspace_id,'settings','manage'));
create trigger workspace_ai_rule_identity before update on public.agency_workspace_ai_rules for each row execute function agency_private.workspace_identity_guard();
alter table public.agency_workspace_action_outbox add column ai_rule_id uuid references public.agency_workspace_ai_rules(id) on delete set null;
create unique index workspace_ai_conversion_dedupe on public.agency_workspace_action_outbox(event_id,ai_rule_id) where ai_rule_id is not null;
create function public.agency_workspace_ai_settings(p_workspace uuid,p_values jsonb default null) returns jsonb language plpgsql security invoker set search_path='' as $$declare r agency_private.workspace_ai_settings;begin
 if p_values is not null then
 insert into agency_private.workspace_ai_settings(workspace_id) values(p_workspace) on conflict do nothing;
 update agency_private.workspace_ai_settings set api_key=coalesce(nullif(trim(p_values->>'api_key'),''),api_key),enabled=coalesce((p_values->>'enabled')::boolean,false),daily_limit=coalesce((p_values->>'daily_limit')::integer,100) where workspace_id=p_workspace;
 if coalesce((p_values->>'enabled')::boolean,false) and exists(select 1 from agency_private.workspace_ai_settings where workspace_id=p_workspace and length(api_key)<20) then raise exception 'Configure uma chave válida do AI Gateway.';end if;
 end if;
 select * into r from agency_private.workspace_ai_settings where workspace_id=p_workspace;return to_jsonb(r);
end;$$;
revoke all on function public.agency_workspace_ai_settings(uuid,jsonb) from public,anon,authenticated;grant execute on function public.agency_workspace_ai_settings(uuid,jsonb) to service_role;
create function agency_private.queue_workspace_ai() returns trigger language plpgsql security definer set search_path='' as $$declare settings agency_private.workspace_ai_settings;begin
 if new.event_type<>'message_received' or new.payload->>'direction'<>'entrada' or coalesce(new.payload->>'kind','texto') not in ('texto','text') or new.lead_id is null or length(trim(coalesce(new.payload->>'message','')))=0 then return new;end if;
 select * into settings from agency_private.workspace_ai_settings where workspace_id=new.workspace_id and enabled;if settings.workspace_id is null then return new;end if;
 if (select count(*) from public.agency_workspace_ai_checks where workspace_id=new.workspace_id and created_at>=(date_trunc('day',now() at time zone 'America/Sao_Paulo') at time zone 'America/Sao_Paulo'))>=settings.daily_limit then return new;end if;
 insert into public.agency_workspace_ai_checks(workspace_id,rule_id,event_id) select new.workspace_id,id,new.id from public.agency_workspace_ai_rules where workspace_id=new.workspace_id and enabled limit greatest(0,settings.daily_limit-(select count(*)::int from public.agency_workspace_ai_checks where workspace_id=new.workspace_id and created_at>=(date_trunc('day',now() at time zone 'America/Sao_Paulo') at time zone 'America/Sao_Paulo'))) on conflict(rule_id,event_id) do nothing;return new;
end;$$;
revoke all on function agency_private.queue_workspace_ai() from public,anon,authenticated;
create trigger workspace_ai_message after insert on public.agency_workspace_events for each row execute function agency_private.queue_workspace_ai();
create function public.agency_workspace_claim_ai(p_workspace uuid) returns jsonb language plpgsql security invoker set search_path='' as $$declare c public.agency_workspace_ai_checks;r public.agency_workspace_ai_rules;e public.agency_workspace_events;s agency_private.workspace_ai_settings;history jsonb;begin
 update public.agency_workspace_ai_checks set status='failed',error='Análise interrompida. Não foi repetida automaticamente para evitar cobrança duplicada.',updated_at=now() where workspace_id=p_workspace and status='processing' and updated_at<now()-interval '2 minutes';
 if not public.agency_workspace_available(p_workspace) then return null;end if;
 select * into s from agency_private.workspace_ai_settings where workspace_id=p_workspace and enabled;if s.workspace_id is null then return null;end if;
 select checks.* into c from public.agency_workspace_ai_checks checks join public.agency_workspace_ai_rules rules on rules.id=checks.rule_id and rules.enabled where checks.workspace_id=p_workspace and checks.status='queued' order by checks.created_at limit 1 for update of checks skip locked;if c.id is null then return null;end if;
 select * into r from public.agency_workspace_ai_rules where id=c.rule_id;select * into e from public.agency_workspace_events where id=c.event_id;
 select jsonb_agg(jsonb_build_object('direction',direction,'text',left(body,2000)) order by created_at) into history from (select direction,body,created_at from public.agency_workspace_messages where workspace_id=p_workspace and account_id::text=e.payload->>'account_id' and phone=e.payload->>'phone' and created_at<=e.created_at and kind='texto' order by created_at desc limit 20) m;
 update public.agency_workspace_ai_checks set status='processing',updated_at=now() where id=c.id;
 return jsonb_build_object('id',c.id,'criteria',r.criteria,'conversation',coalesce(history,'[]'),'api_key',s.api_key,'model',s.model);
end;$$;
revoke all on function public.agency_workspace_claim_ai(uuid) from public,anon,authenticated;grant execute on function public.agency_workspace_claim_ai(uuid) to service_role;
create table agency_private.workspace_ai_matches(workspace_id uuid not null,rule_id uuid not null,lead_id uuid not null,created_at timestamptz not null default now(),primary key(rule_id,lead_id),foreign key(rule_id,workspace_id) references public.agency_workspace_ai_rules(id,workspace_id) on delete cascade,foreign key(lead_id,workspace_id) references public.agency_workspace_leads(id,workspace_id) on delete cascade);
alter table agency_private.workspace_ai_matches enable row level security;revoke all on agency_private.workspace_ai_matches from public,anon,authenticated;grant all on agency_private.workspace_ai_matches to service_role;
create function public.agency_workspace_finish_ai(p_id uuid,p_match boolean,p_error text default null) returns void language plpgsql security invoker set search_path='' as $$declare c public.agency_workspace_ai_checks;r public.agency_workspace_ai_rules;e public.agency_workspace_events;l public.agency_workspace_leads;begin
 select * into c from public.agency_workspace_ai_checks where id=p_id and status='processing' for update;if c.id is null then return;end if;select * into r from public.agency_workspace_ai_rules where id=c.rule_id;
 if not r.enabled or not public.agency_workspace_available(c.workspace_id) or not exists(select 1 from agency_private.workspace_ai_settings where workspace_id=c.workspace_id and enabled) then update public.agency_workspace_ai_checks set status='cancelled',updated_at=now() where id=c.id;return;end if;
 update public.agency_workspace_ai_checks set status=case when p_error is not null then 'failed' when p_match then 'matched' else 'ignored' end,error=left(p_error,300),updated_at=now() where id=c.id;
 if p_error is null and p_match then
 select * into e from public.agency_workspace_events where id=c.event_id;select * into l from public.agency_workspace_leads where id=e.lead_id and workspace_id=c.workspace_id;if l.id is null then return;end if;
 insert into agency_private.workspace_ai_matches(workspace_id,rule_id,lead_id) values(c.workspace_id,r.id,l.id) on conflict(rule_id,lead_id) do nothing;if not found then update public.agency_workspace_ai_checks set status='ignored',error='Este critério já foi registrado para este lead.' where id=c.id;return;end if;
 insert into public.agency_workspace_action_outbox(workspace_id,event_id,ai_rule_id,action,payload) values(c.workspace_id,e.id,r.id,case r.provider when 'meta' then 'meta_event' else 'google_conversion' end,jsonb_build_object('event_name',r.event_name,'lead_id',l.id,'phone',l.phone,'email',l.email,'attributes',l.attributes,'value',case when r.value>0 then r.value else l.value end)) on conflict(event_id,ai_rule_id) where ai_rule_id is not null do nothing;
 end if;
end;$$;
revoke all on function public.agency_workspace_finish_ai(uuid,boolean,text) from public,anon,authenticated;grant execute on function public.agency_workspace_finish_ai(uuid,boolean,text) to service_role;
create function agency_private.cancel_workspace_ai_rule() returns trigger language plpgsql security definer set search_path='' as $$begin
 if tg_op='DELETE' or not new.enabled then update public.agency_workspace_ai_checks set status='cancelled' where rule_id=old.id and status='queued';update public.agency_workspace_action_outbox set status='cancelled',error='Regra de IA desativada ou removida.' where ai_rule_id=old.id and status='queued';end if;if tg_op='DELETE' then return old;end if;return new;
end;$$;
revoke all on function agency_private.cancel_workspace_ai_rule() from public,anon,authenticated;
create trigger workspace_ai_rule_cancel before update of enabled or delete on public.agency_workspace_ai_rules for each row execute function agency_private.cancel_workspace_ai_rule();

alter table public.agency_workspace_ai_rules add constraint workspace_ai_meta_event check(provider<>'meta' or event_name~'^[A-Za-z][A-Za-z0-9_]{0,59}$');
do $$begin if to_regprocedure('cron.schedule(text,text,text)') is not null then perform cron.schedule('pilot-workspace-ai','* * * * *',$job$ select net.http_post(url:='https://dycyskikaljvokaxsxnh.supabase.co/functions/v1/workspace-operations?worker='||c.worker_secret,headers:='{"Content-Type":"application/json"}'::jsonb,body:='{}'::jsonb,timeout_milliseconds:=55000) from agency_private.workspace_whatsapp c join public.agency_client_workspaces w on w.id=c.workspace_id and w.status='active' join agency_private.pilot_accounts p on p.user_id=w.owner_user_id and p.enabled where c.enabled and exists(select 1 from public.agency_workspace_ai_checks a where a.workspace_id=c.workspace_id and a.status in ('queued','processing')); $job$);end if;end;$$;
